(function () {const UI =window.DarcyUI;const cta =(title,body ='Tell us what you are considering. We will listen first, then offer a clear and honest view of the best next step.') =>UI.CTAPanel({variant:'relationship',title,body });const hero =(title,intro,eyebrow) =>UI.Hero({variant:'internal',eyebrow,title,body:intro });const heading =(eyebrow,title,body,id) =>UI.SectionHeader({eyebrow,title,body,id });const placeholder =text => ``;const image =(src,alt) =>`<div class="split-image">${UI.ResponsiveImage({ src, alt, width: 1200, height: 800, loading: 'lazy' })}</div>`;const editorialSplit =({src,alt,eyebrow,title,body,link ='#contact',label ='Start a conversation'}) =>`<section class="split">${image(src, alt)}<div class="split-copy"><span class="eyebrow">${eyebrow}</span><h2>${title}</h2>${body}<a class="text-link" href="${link}">${label} <span aria-hidden="true">→</span></a></div></section>`;const values =[['01','Relationships first','The quality of the working relationship shapes the quality of every decision.'],['02','Honest advice','We say what will help the project—even when it is not the easiest answer.'],['03','Pride in the detail','Craft, coordination and care are visible in the finished place.'] ];const valueCards =() =>`<div class="cards">${values.map(v=>`<article class="card"><span class="number">${v[0]}</span><h3>${v[1]}</h3><p>${v[2]}</p></article>`).join('')}</div>`;const guidance =(eyebrow,title,intro,items,id) =>`<section class="section guidance" aria-labelledby="${id}">${heading(eyebrow,title,intro,id)}<div class="cards">${items.map((item,i)=>`<article class="card"><span class="number">${String(i+1).padStart(2,'0')}</span><h3>${item[0]}</h3><p>${item[1]}</p></article>`).join('')}</div></section>`;const sectorLinks =() =>`<div class="sector-links">${[['Commercial','commercial','Places that help organisations perform.'],['Residential','residential','Homes shaped around real lives.'],['Education','education','Safe, inspiring places to learn.'],['Community','community','Buildings with a wider purpose.']].map(s=>`<a href="#${s[1]}"><span>${s[0]}</span><p>${s[2]}</p><i aria-hidden="true">↗</i></a>`).join('')}</div>`;const caseStudySection =(eyebrow,title,body,id) =>`<section class="section case-narrative" aria-labelledby="${id}">${heading(eyebrow,title,'',id)}<div class="case-copy">${body}</div></section>`;const caseStudyTemplate =project =>`${UI.CaseStudyHero(project)} <section class="trustbar case-facts" aria-label="Project snapshot">${project.snapshot.map(item=>`<div><span class="trust-number">${item.value}</span><span>${item.label}</span></div>`).join('')}</section> ${caseStudySection('Overview','The ambition',project.overview,'case-overview')} ${caseStudySection('The challenge','What needed to be protected?',project.challenge,'case-challenge')} ${caseStudySection('Our approach','How Darcy made progress feel controlled.',project.approach,'case-approach')} ${caseStudySection('The outcome','A successful handover, evidenced without exaggeration.',project.outcome,'case-outcome')} <section class="section project-facts" aria-labelledby="project-facts-title">${heading('Project facts','The verified record.','Unknown fields remain visible so Darcy can approve, amend or remove them before launch.','project-facts-title')}${UI.FactList(project.facts)}</section> <section class="section case-gallery" aria-labelledby="case-gallery-title">${heading('Gallery','Darcy-owned photography only.','Only images published on Darcy’s current website are used here. Additional gallery images can be added once ownership and permissions are confirmed.','case-gallery-title')}<div class="gallery-grid">${project.gallery.map(image=>`<figure>${UI.ResponsiveImage({src:image.src,alt:image.alt,width:1200,height:800,loading:'lazy'})}<figcaption>${image.caption}</figcaption></figure>`).join('')}</div></section> ${project.testimonial ? `<section class="quote case-quote"><span class="eyebrow">Verified client voice</span><blockquote>${project.testimonial.quote}</blockquote><cite>${project.testimonial.name} · ${project.testimonial.context}</cite></section>` : `<section class="section case-testimonial-pending"aria-labelledby="case-testimonial-title">${heading('Client voice','Testimonial pending approval.','No verified testimonial is currently published for this project. Add one only when Darcy has approved the quotation, attribution and permission to publish.','case-testimonial-title')}</section>`} <section class="section featured-work related-projects" aria-labelledby="related-projects-title">${heading('Related projects','More stories to build next.','These are real Darcy projects already identified for the portfolio. Their full case studies require the same evidence-led production process.','related-projects-title')}<div class="featured-projects">${project.related.map(UI.ProjectCard).join('')}</div></section> ${cta(project.ctaTitle,project.ctaBody)}`;const Pages ={story() {const difference=[{number:'01',title:'You get experience without distance.',body:'Senior people remain close to your project, so decisions are informed and accountability stays clear.',services:'Major-contractor expertise · Local accessibility'},{number:'02',title:'You hear the honest answer.',body:'We communicate openly about cost, risk and programme—even when the useful answer is not the easiest one.',services:'Clear advice · Transparent communication'},{number:'03',title:'You feel the care in the detail.',body:'We protect the quality of the finished place while remembering the people who will use it every day.',services:'Craftsmanship · Quality · Aftercare'} ];const brandValues=[['01','Relationships','We build trust by listening carefully, communicating openly and doing what we say.'],['02','Integrity','Professionalism and fairness guide the difficult decisions as much as the easy ones.'],['03','Collaboration','The strongest outcomes come from clients, consultants and builders working as one team.'],['04','Quality','We never treat craftsmanship as decoration. It is a responsibility to the client and the place.'],['05','Community','We want our work to strengthen the people, organisations and places around it.'],['06','Pride','We leave behind projects and relationships we will be proud to stand beside for years.'] ];const leaders=[['Parminder Mew','Founder and Managing Director','A collaborative problem-solver who keeps client vision and fine detail in view.'],['Robert Mew','Construction Director','Experienced site leadership focused on quality, coordination and dependable delivery.'],['Peter Oliver','Commercial Director','Commercial clarity and considered advice from early planning through completion.'] ];return `${hero('Our story','A trusted construction partner combining major-contractor experience with the personal commitment of a local business.','Established 1999 · Romsey')} ${editorialSplit({src:'https://darcyconstruction.co.uk/wp-content/uploads/2021/07/community-550x450x.jpg',alt:'A close team in conversation around a shared table',eyebrow:'Since 1999',title:'Built locally.<br>Thinking long term.',body:'<p>Darcy began in Romsey with three construction professionals and a shared belief: clients deserved serious expertise without becoming distant from the people responsible for their project.</p><p>More than twenty-five years later, that idea still shapes how we work. We have grown through repeat relationships, honest conversations and projects completed with pride.</p>',link:'#approach',label:'See how we work'})} <section class="section story-purpose" aria-labelledby="story-purpose">${heading('Our purpose','To make construction feel collaborative, transparent and genuinely enjoyable.','A project should not leave you feeling managed from a distance. It should give you confidence that the right people understand the ambition, are honest about the constraints and care about the outcome as much as you do.','story-purpose')}<section class="quote embedded-quote"><blockquote>“We exist to turn ideas into places people value—and to build relationships that last beyond handover.”</blockquote><cite>The Darcy purpose</cite></section></section> <section class="section outcomes story-difference" aria-labelledby="story-difference">${heading('The Darcy difference','The best of both worlds.','The knowledge and discipline of a major contractor, delivered with the accessibility and personal responsibility of a local team.','story-difference')}<div class="outcome-list">${difference.map(UI.ServiceCard).join('')}</div></section> <section class="section story-values" aria-labelledby="story-values">${heading('Brand values','The standards behind every decision.','These are not statements for a wall. They describe how clients, colleagues and partners should experience Darcy.','story-values')}<div class="cards values-grid">${brandValues.map(v=>`<article class="card"><span class="number">${v[0]}</span><h3>${v[1]}</h3><p>${v[2]}</p></article>`).join('')}</div></section> <section class="section team-preview" aria-labelledby="team-title">${heading('Meet the team','Familiar faces. Clear accountability.','Darcy is led by three directors whose complementary experience has been built over decades of working together.','team-title')}<div class="cards">${leaders.map((person,i)=>`<article class="card team-card"><span class="number">0${i+1}</span><h3>${person[0]}</h3><strong>${person[1]}</strong><p>${person[2]}</p></article>`).join('')}</div><a class="text-link section-link" href="#careers">Meet the wider Darcy team <span aria-hidden="true">→</span></a></section> ${editorialSplit({src:'https://darcyconstruction.co.uk/wp-content/uploads/2021/07/community-550x450@2x.jpg',alt:'Sozo Ministries community project delivered by Darcy Construction',eyebrow:'Community and local roots',title:'Proudly from Romsey.<br>Invested in Hampshire.',body:'<p>Our local roots shape how we think about responsibility. We work with schools, charities, organisations, developers and homeowners whose projects become part of the same communities in which our team lives and works.</p><p>That proximity matters. Reputation is not abstract when clients become long-term partners and completed buildings become familiar local places.</p>',link:'#community',label:'Explore our community work'})} ${cta('Begin with a conversation, not a brief.','Tell us what you are hoping to make possible. We will listen first and offer an honest view of the best next step.')}`;},approach() {const steps=[['01','Meet','You get an open first conversation, without pressure or a predetermined answer.'],['02','Understand','We explore the ambition, constraints and people your project needs to serve.'],['03','Plan','You receive a clear route through scope, cost, risk, programme and responsibilities.'],['04','Build','We manage the detail and keep you informed without making the project your full-time job.'],['05','Support','We remain available through handover, settling-in and aftercare.']];return `${hero('Our approach','A calm, accountable path from the first conversation to long after handover.','The Darcy Standard')} <section class="section process internal-process" aria-labelledby="approach-process">${heading('How we work','Clarity at every stage.','Our process is designed around what you need to know, decide and feel confident about.','approach-process')}${UI.ProcessTimeline(steps.map(s=>({number:s[0],title:s[1],body:s[2]})))}</section> ${editorialSplit({src:'https://darcyconstruction.co.uk/wp-content/uploads/2021/07/community-550x450x.jpg',alt:'A collaborative project planning conversation',eyebrow:'What partnership means',title:'No surprises.<br>No disappearing acts.',body:'<p>You should always know who is accountable and where the project stands. We communicate directly, surface difficult decisions early and keep senior experience close to the work.</p>',link:'#contact'})} <section class="section"><div class="section-intro"><span class="eyebrow">What you can expect</span><div><h2>Professional systems.<br>Human delivery.</h2><p>Strong controls should create confidence, not bureaucracy.</p></div></div>${valueCards()}</section> ${cta('Bring us the ambition—and the awkward questions.')}`;},services() {const outcomes=[{number:'01',title:'You need confidence before committing.',body:'We test feasibility, budget, programme and risk while change is still affordable.',services:'Pre-construction · Cost planning · Project management'},{number:'02',title:'You need complexity to feel manageable.',body:'We coordinate people, design, information and delivery around one accountable plan.',services:'Main contracting · Design coordination · Construction management'},{number:'03',title:'You need quality without losing commercial control.',body:'We protect the details that matter while maintaining clear decisions, reporting and cost discipline.',services:'New build · Refurbishment · Bespoke development'} ];return `${hero('What we do','We organise our expertise around the outcome you need—not around internal departments.','Capability without complexity')} <section class="section outcomes" aria-labelledby="service-outcomes">${heading('Start with the problem','What does the project need to solve?','The right service becomes clearer once the ambition, constraints and risks are understood.','service-outcomes')}<div class="outcome-list">${outcomes.map(UI.ServiceCard).join('')}</div></section> <section class="section service-detail"><div class="section-intro"><span class="eyebrow">Our capability</span><div><h2>One team from thinking to making.</h2><p>You can involve Darcy early, appoint us for delivery, or ask us to provide continuity across both.</p></div></div><div class="cards">${[['01','Construction management','Feasibility, buildability, cost planning, procurement and programme clarity.','#construction-management'],['02','Refurbishment','Careful renewal planned around existing buildings, live operations and the people who use them.','#refurbishment'],['03','Main contracting','Accountable delivery, coordination, quality, safety and communication on site.','#contact']].map(v=>`<a class="card linked-card"href="${v[4]}"><span class="number">${v[0]}</span><h3>${v[1]}</h3><p>${v[2]}</p><span class="card-link">Explore <i aria-hidden="true">→</i></span></a>`).join('')}</div></section> ${cta('Not sure which service you need? Good.','Start with the project, not a procurement label. We will help you clarify the right route.')}`;},sectors() {return `${hero('Who we work for','Different sectors bring different pressures. The Darcy principles remain the same: listen, plan carefully and stay accountable.','Experience applied personally')}<section class="section">${heading('Sectors','Built around how people use the place.','Our work spans organisations, homeowners, schools and community groups across Hampshire.','sector-title')}${sectorLinks()}</section>${cta('Tell us what the building needs to make possible.')}`;},commercial() {return `${hero('Commercial','Spaces that support the organisation behind them—delivered with commercial clarity and minimal disruption.','Who we work for')} ${editorialSplit({src:'https://darcyconstruction.co.uk/wp-content/uploads/2021/07/community-550x450x.jpg',alt:'A completed contemporary workplace in use',eyebrow:'Your priorities',title:'Keep the business moving.',body:'<p>You need certainty on cost, programme and operational impact. We plan around live environments, decision deadlines and the people who still need to use the building.</p>',link:'#contact'})} <section class="section">${heading('What we solve','Commercial pressure without construction noise.','Darcy brings early risk visibility, disciplined coordination and one direct line of accountability.','commercial-solutions')}${valueCards()}</section> ${guidance('Before work begins','Protect the operation as carefully as the programme.','The best commercial projects make disruption a design input from the start.',[['Map critical business activity','Identify people, access, technology and trading periods that construction cannot casually interrupt.'],['Set decision deadlines','Connect approvals to procurement and programme consequences so choices are made with context.'],['Define success beyond handover','Agree how the finished place should improve performance, experience or long-term value.']],'commercial-guidance')} ${placeholder('Replace with verified commercial client names, project outcomes and photography before publication.')} ${cta('Planning change without stopping business?')}`;},residential() {return `${hero('Residential','A home is personal. The process of creating it should feel personal too.','Who we work for')} ${editorialSplit({src:'https://darcyconstruction.co.uk/wp-content/uploads/2021/07/055-550x450@2x.jpg',alt:'A completed Darcy residential project',eyebrow:'A home, not a product',title:'Built around how you live.',body:'<p>We translate ambition into clear choices, protect the details you care about and communicate openly through a process that can otherwise feel consuming.</p>',link:'#contact'})} <section class="section">${heading('What homeowners ask','Will you listen? Will I know what is happening? Will the details be right?','Our residential approach is designed to answer yes—and keep answering it throughout.','residential-questions')}${valueCards()}</section> <section class="quote"><span class="eyebrow">Homeowner</span><blockquote>“It is pure pleasure to live in.”</blockquote><cite>Franny & Paul Hornblow · Darcy-built home</cite></section> ${guidance('A useful place to start','Turn preferences into priorities.','Clarity early gives the design and budget room to serve the life you want to live.',[['Describe the everyday moments','Talk about arrival, light, storage, gathering and retreat—not only rooms and finishes.'],['Separate essentials from possibilities','A clear hierarchy makes later cost and design decisions calmer and more consistent.'],['Agree how choices will be made','Define who decides, what information they need and when each decision affects the build.']],'residential-guidance')} ${cta('Tell us what home needs to feel like.')}`;},education() {return `${hero('Education','Safe, carefully phased projects that protect learning while improving the places where it happens.','Who we work for')} ${editorialSplit({src:'https://darcyconstruction.co.uk/wp-content/uploads/2021/07/community-550x450x.jpg',alt:'Students using a bright contemporary education building',eyebrow:'Live environments',title:'The school stays a school.',body:'<p>Programme, safeguarding, access and communication are planned around pupils and staff—not treated as site inconveniences.</p>',link:'#contact'})} <section class="section">${heading('What matters','Safe delivery. Fixed windows. Clear accountability.','We coordinate holiday works, operational interfaces and specialist teams while keeping stakeholders informed.','education-priorities')}${valueCards()}</section> <section class="quote"><span class="eyebrow">Repeat education client</span><blockquote>“The end result is much acclaimed.”</blockquote><cite>Farleigh School · Education refurbishment</cite></section> ${guidance('Planning around learning','Start with the school day.','A reliable delivery plan reflects safeguarding, examinations, term dates and the practical life of the campus.',[['Name the immovable dates','Work backwards from occupation, examinations and term changes with realistic commissioning time.'],['Plan every interface','Separate pupils, staff, deliveries and construction activity with clear ownership and communication.'],['Prepare for handover early','Training, certification, familiarisation and defects planning should not wait for the final week.']],'education-guidance')} ${cta('Planning works around a live school?')}`;},community() {return `${hero('Community','Buildings with a wider purpose deserve a contractor who understands more than the brief.','Who we work for')} ${editorialSplit({src:'https://darcyconstruction.co.uk/wp-content/uploads/2021/07/community-550x450@2x.jpg',alt:'Sozo Ministries community project by Darcy Construction',eyebrow:'Shared purpose',title:'Every pound—and every decision—matters.',body:'<p>We work collaboratively with charities and community organisations, balancing ambition, budget, heritage and the needs of the people who rely on the place.</p>',link:'#contact'})} <section class="section">${heading('What we bring','Careful stewardship. Practical ingenuity.','We help teams make confident trade-offs without losing sight of the project’s purpose.','community-value')}${valueCards()}</section> ${guidance('Making the brief work harder','Keep purpose visible in every trade-off.','Community projects benefit when trustees, users, funders and the delivery team share one decision framework.',[['Listen to the people who use it','Early user insight exposes practical needs that drawings and governance papers can miss.'],['Connect scope to impact','Rank investment by the difference it makes to access, service delivery and long-term resilience.'],['Build a transparent decision trail','Clear assumptions and approvals help boards and funders govern the project with confidence.']],'community-guidance')} ${placeholder('Add approved community impact figures and client permissions before publication.')} ${cta('Let’s talk about the purpose behind the project.')}`;},'construction-management'() {return `${hero('Construction Management','Experienced leadership that keeps design, procurement, cost and delivery moving as one accountable programme.','What we do')} ${editorialSplit({src:'https://darcyconstruction.co.uk/wp-content/uploads/2021/07/community-550x450x.jpg',alt:'Construction team reviewing a live project on site',eyebrow:'The promise',title:'Complexity,<br>made clear.',body:'<p>You retain visibility and flexibility while Darcy provides the structure, coordination and experienced judgement needed to keep the project moving.</p><p>We make responsibilities explicit, surface risk early and turn a changing set of decisions into one controlled route to completion.</p>',link:'#contact'})} <section class="section outcomes" aria-labelledby="cm-evidence">${heading('What this gives you','Control without carrying every detail.','The service is shaped around the decisions and assurances the client needs—not around our internal process.','cm-evidence')}<div class="outcome-list">${[ {number:'01',title:'You see the real position early.',body:'Cost, programme, procurement and design information are reviewed together so emerging pressure is visible before it becomes disruption.',services:'Transparent reporting · Risk visibility'}, {number:'02',title:'The right people arrive at the right time.',body:'Work packages, specialist appointments and information releases are coordinated around the programme and the project’s priorities.',services:'Procurement · Design coordination'}, {number:'03',title:'Decisions stay connected to the outcome.',body:'One experienced team holds the whole picture, helping you understand the consequence of each choice before you commit.',services:'Senior leadership · Client guidance'} ].map(UI.ServiceCard).join('')}</div></section> ${guidance('Before you appoint','Three useful questions to ask.','A good construction management partner should make the commercial and practical reality easier to understand.',[['Who remains accountable?','Know who will lead day to day, who has authority and how senior oversight stays close.'],['How will cost be reported?','Agree how forecasts, package commitments, risk and change will be presented before work begins.'],['When are decisions needed?','A useful programme shows client and design decisions alongside construction activity—not after it.']],'cm-guidance')} ${placeholder('Add verified construction management project evidence, outcomes and an approved client quotation before publication.')} ${cta('Need a clearer route through a complex project?')}`;},refurbishment() {return `${hero('Refurbishment','Thoughtful renewal that respects what is already there—and protects the people who still need the building to work.','What we do')} ${editorialSplit({src:'https://darcyconstruction.co.uk/wp-content/uploads/2022/02/NR174808-min-550x450@2x.jpg',alt:'A completed Darcy refurbishment project',eyebrow:'The promise',title:'Improve the place.<br>Protect what matters.',body:'<p>Existing buildings reveal their complexity gradually. We investigate carefully, plan for uncertainty and phase work around the client’s operational reality.</p><p>The result should feel considered rather than compromised: a renewed place that works better without losing the character worth keeping.</p>',link:'#contact'})} <section class="section outcomes" aria-labelledby="refurb-evidence">${heading('What this solves','Confidence when not everything can be seen.','Refurbishment needs practical judgement, close communication and room to respond without losing control.','refurb-evidence')}<div class="outcome-list">${[ {number:'01',title:'You understand the unknowns.',body:'Early surveys and buildability reviews identify likely constraints, dependencies and decisions while there is still time to plan around them.',services:'Investigation · Risk planning'}, {number:'02',title:'Your organisation keeps functioning.',body:'Access, noise, dust, safeguarding and temporary arrangements are planned around the people using the building.',services:'Live environments · Phasing'}, {number:'03',title:'Old and new feel resolved.',body:'We coordinate services, finishes and retained fabric with care so the completed place feels coherent, useful and built to last.',services:'Craftsmanship · Quality control'} ].map(UI.ServiceCard).join('')}</div></section> ${guidance('Planning a refurbishment','Start before the strip-out.','These early actions create a more reliable brief, budget and programme.',[['Record how the building is used','Map occupancy, access, critical operations and periods when disruption would be most damaging.'],['Investigate before pricing','Targeted surveys reduce assumptions and make risk allowances more meaningful.'],['Agree what must be protected','Identify the character, fabric, equipment and relationships that cannot be treated as replaceable.']],'refurb-guidance')} ${placeholder('Add verified refurbishment project facts, before-and-after photography and an approved client quotation before publication.')} ${cta('Planning change in an existing building?')}`;},work() {const projects=[{title:'Sozo Ministries',story:'A place with purpose, protected through change.',image:'https://darcyconstruction.co.uk/wp-content/uploads/2021/07/community-550x450@2x.jpg',href:'#case-study'},{title:'Pauncefoot House',story:'An established home, renewed for the life ahead.',image:'https://darcyconstruction.co.uk/wp-content/uploads/2021/07/055-550x450@2x.jpg',href:'#pauncefoot-house'},{title:'Canada Common',story:'A rural home shaped with patience and precision.',image:'https://darcyconstruction.co.uk/wp-content/uploads/2022/03/Capture-550x450.jpg',href:'#canada-common'},{title:'QE2 Activity Centre',story:'A community setting designed around access and possibility.',image:'https://darcyconstruction.co.uk/wp-content/uploads/2022/02/dining-scaled-550x450@2x.jpg',href:'#work'},{title:'October Books',story:'A valued independent organisation given room for its next chapter.',image:'https://darcyconstruction.co.uk/wp-content/uploads/2022/02/NR174808-min-550x450@2x.jpg',href:'#work'},{title:'Devenish House',story:'A Winchester home where character and contemporary life meet.',image:'https://darcyconstruction.co.uk/wp-content/uploads/2022/02/WND210002_12_l_gal-550x450@2x.jpg',href:'#work'} ];return `${hero('Projects','Not a gallery of buildings. A collection of client ambitions, constraints and outcomes.','Our work')} <section class="section featured-work project-index">${heading('Selected work','The story behind each place.','Explore how Darcy listens, solves and delivers across residential, education, commercial and community projects.','projects-title')}<div class="featured-projects">${projects.map(UI.ProjectCard).join('')}</div></section> ${placeholder('Project values, dates, consultant teams and performance outcomes must be verified before launch.')} ${cta('Have a project story waiting to begin?')}`;},'case-study'() {const sozo={title:'Sozo Ministries Conference Hall',sector:'Community',location:'Location to confirm',image:'https://darcyconstruction.co.uk/wp-content/uploads/2021/07/community.jpg',imageAlt:'Sozo Ministries Conference Hall project by Darcy Construction',intro:'A verified Darcy community project, rebuilt here as an evidence-led case study rather than a list of unsupported claims.',snapshot:[{value:'Community',label:'Sector'},{value:'Conference hall',label:'Published project scope'},{value:'On time',label:'Verified handover note'},{value:'Within budget',label:'Verified handover note'} ],overview:'<p>The current Darcy website identifies the project as <strong>Sozo Ministries Conference Hall</strong>. That gives the first editorial truth of the case study: this was a community project where the finished place needed to serve people, gatherings and purpose.</p><p>The detailed client ambition still needs approval from Darcy before launch, so this first version holds the story open rather than inventing what cannot yet be evidenced.</p>',challenge:'<p>The official Darcy case study verifies that the project included a new conference hall and associated office works forming part of a listed building.</p><p>It also confirms a terraced setting with neighbouring properties requiring party wall agreements, coordinated by Darcy. Detailed stakeholder requirements and client ambition should still be confirmed before launch.</p>',approach:'<p>The official Darcy case study identifies this as a design and build project. Published works included a steel frame structure, brickwork and partial cladding, curtain wall screening, high-level internal finishes, external works, a new roof, a new extension and the removal of large structural elements.</p><p>Before launch, this section can still be strengthened with Darcy’s project lead account: how the team planned the work, communicated with Sozo Ministries and protected the client’s priorities through delivery.</p>',outcome:'<p>The existing Darcy case-study page states: <strong>“The building was successfully handed over with the client on-time and within budget.”</strong></p><p>That is the core verified outcome for this first flagship case study. Long-term value, community impact and user experience should be added only once approved by Darcy or supported by client evidence.</p>',facts:[{label:'Project',value:'Sozo Ministries Conference Hall'},{label:'Client',value:'To confirm with Darcy'},{label:'Sector',value:'Community'},{label:'Location',value:'To confirm with Darcy'},{label:'Scope',value:'New conference hall, associated offices and external works'},{label:'Procurement route',value:'Design and build'},{label:'Completion date',value:'To confirm with Darcy'},{label:'Published source',value:'Current Darcy case-study page'} ],gallery:[{src:'https://darcyconstruction.co.uk/wp-content/uploads/2021/07/community.jpg',alt:'Sozo Ministries Conference Hall completed by Darcy Construction',caption:'Published Darcy project photography for Sozo Ministries.'} ],testimonial:{quote:'“Darcy have been very professional, showing integrity, efficiency and diligence on the whole project to date. I would have no problems recommending them.”',name:'Alan Daniel',context:'Sozo Ministries case-study testimonial'},related:[{title:'QE2 Activity Centre',story:'A community setting designed around access and possibility.',image:'https://darcyconstruction.co.uk/wp-content/uploads/2022/02/dining-scaled-550x450@2x.jpg',href:'#work'},{title:'October Books',story:'A valued independent organisation given room for its next chapter.',image:'https://darcyconstruction.co.uk/wp-content/uploads/2022/02/NR174808-min-550x450@2x.jpg',href:'#work'},{title:'Devenish House',story:'A Winchester home where character and contemporary life meet.',image:'https://darcyconstruction.co.uk/wp-content/uploads/2022/02/WND210002_12_l_gal-550x450@2x.jpg',href:'#work'} ],ctaTitle:'Have a community project that needs careful stewardship?',ctaBody:'Start with a conversation. Darcy will listen first, then help you understand the route, risks and decisions that will shape a confident project.'};return caseStudyTemplate(sozo);},'pauncefoot-house'() {const project={title:'Pauncefoot House',sector:'Residential',location:'Chilworth',image:'https://darcyconstruction.co.uk/wp-content/uploads/2021/07/055.jpg',imageAlt:'Pauncefoot House residential project by Darcy Construction',intro:'A verified Darcy residential project shaped around open-plan family living, careful detailing and a balance of traditional and modern character.',snapshot:[{value:'Residential',label:'Sector'},{value:'Chilworth',label:'Published location'},{value:'5-bed home',label:'Published scope'},{value:'3,750 sqft',label:'Published size'} ],overview:'<p>The current Darcy case-study page identifies Pauncefoot House as a comfortable five-bed, 3,750 sqft family home in Chilworth.</p><p>The published description centres on open-plan living spaces, a timber staircase, a wood-burning fireplace and a high standard of finish throughout. This gives the case study a clear residential ambition: a home that balances everyday family use with carefully composed detail.</p>',challenge:'<p>The live Darcy page does not publish site constraints, planning conditions, budget requirements or programme pressures for Pauncefoot House.</p><p>What can be evidenced is the design and finish challenge: creating large, open social spaces while balancing a traditional and modern internal palette, garden-facing glazing and high-quality room-by-room finishes.</p>',approach:'<p>The verified project description highlights the elements that required care in coordination: a timber staircase, wood-burning fireplace, large-scale glazing, a Biefbi Cucine fitted kitchen and a mixed internal material palette.</p><p>Darcy’s detailed delivery story should be confirmed before launch. The final version should explain how these features were coordinated, protected and finished on site without inventing a delivery narrative from the published description alone.</p>',outcome:'<p>The published outcome is a five-bedroom family home with well thought-out open-plan living spaces, a high standard of finish and rear living space with large-scale glazing providing views of the garden.</p><p>Client experience, long-term residential value and any project performance outcomes should be added only once approved by Darcy or the client.</p>',facts:[{label:'Project',value:'Pauncefoot House'},{label:'Client',value:'To confirm with Darcy'},{label:'Sector',value:'Residential'},{label:'Location',value:'Chilworth'},{label:'Scope',value:'Five-bed family home'},{label:'Size',value:'3,750 sqft'},{label:'Procurement route',value:'To confirm with Darcy'},{label:'Completion date',value:'To confirm with Darcy'} ],gallery:[{src:'https://darcyconstruction.co.uk/wp-content/uploads/2021/07/055.jpg',alt:'Pauncefoot House completed residential interior by Darcy Construction',caption:'Published Darcy project photography for Pauncefoot House.'} ],related:[{title:'Canada Common',story:'A rural home shaped with patience and precision.',image:'https://darcyconstruction.co.uk/wp-content/uploads/2022/03/Capture.jpg',href:'#canada-common'},{title:'Devenish House',story:'A Winchester home where character and contemporary life meet.',image:'https://darcyconstruction.co.uk/wp-content/uploads/2022/02/WND210002_12_l_gal-550x450@2x.jpg',href:'#work'},{title:'Sozo Ministries Conference Hall',story:'A place with purpose, protected through change.',image:'https://darcyconstruction.co.uk/wp-content/uploads/2021/07/community.jpg',href:'#case-study'} ],ctaTitle:'Planning a home where the details really matter?',ctaBody:'Start with a conversation about how you want the finished place to feel, work and last.'};return caseStudyTemplate(project);},'canada-common'() {const project={title:'Canada Common',sector:'Residential',location:'West Wellow',image:'https://darcyconstruction.co.uk/wp-content/uploads/2022/03/Capture.jpg',imageAlt:'Canada Common detached house by Darcy Construction',intro:'A verified Darcy residential project: a traditional-build detached house in the New Forest National Park, completed to a high specification.',snapshot:[{value:'Residential',label:'Sector'},{value:'West Wellow',label:'Published location'},{value:'Detached house',label:'Published scope'},{value:'New Forest',label:'Published setting'} ],overview:'<p>The current Darcy website describes Canada Common as a new traditional-build detached house in West Wellow, located in the New Forest National Park.</p><p>The published description focuses on high specification detailing: lime mortar throughout, on-site joinery works, specialist brick details, conservation roof lighting and bespoke timber windows and bi-fold doors.</p>',challenge:'<p>The published content does not identify planning constraints, budget, programme, client requirements or site conditions.</p><p>The verified challenge is one of craft and setting: delivering a traditional-build detached house in the New Forest National Park with specialist detailing and bespoke timber elements.</p>',approach:'<p>The case-study source confirms a high-specification approach with lime mortar throughout, on-site joinery, specialist brick details, conservation roof lighting and bespoke timber windows and bi-fold doors.</p><p>The final Darcy delivery narrative should be added once the project team confirms how these details were planned, procured and coordinated on site.</p>',outcome:'<p>The verified outcome is a completed traditional-build detached house delivered to a high specification, with the published craftsmanship details forming the strongest current evidence.</p><p>Client feedback, performance outcomes and long-term value should remain approval-gated until supplied or approved by Darcy.</p>',facts:[{label:'Project',value:'Canada Common'},{label:'Client',value:'To confirm with Darcy'},{label:'Sector',value:'Residential'},{label:'Location',value:'West Wellow'},{label:'Setting',value:'New Forest National Park'},{label:'Scope',value:'Traditional-build detached house'},{label:'Procurement route',value:'To confirm with Darcy'},{label:'Completion date',value:'To confirm with Darcy'} ],gallery:[{src:'https://darcyconstruction.co.uk/wp-content/uploads/2022/03/Capture.jpg',alt:'Canada Common completed detached house by Darcy Construction',caption:'Published Darcy project photography for Canada Common.'} ],related:[{title:'Pauncefoot House',story:'An established home, renewed for the life ahead.',image:'https://darcyconstruction.co.uk/wp-content/uploads/2021/07/055.jpg',href:'#pauncefoot-house'},{title:'Devenish House',story:'A Winchester home where character and contemporary life meet.',image:'https://darcyconstruction.co.uk/wp-content/uploads/2022/02/WND210002_12_l_gal-550x450@2x.jpg',href:'#work'},{title:'Farleigh School',story:'A repeat-client education relationship delivered around live school needs.',image:'https://darcyconstruction.co.uk/wp-content/uploads/2021/07/staff-room-4-2-1024x682.jpg',href:'#farleigh-school'} ],ctaTitle:'Building in a sensitive setting?',ctaBody:'Tell us what the place needs to protect as well as what the project needs to create.'};return caseStudyTemplate(project);},'farleigh-school'() {const project={title:'Farleigh School',sector:'Education',location:'Location to confirm',image:'https://darcyconstruction.co.uk/wp-content/uploads/2021/07/staff-room-4-2-scaled.jpg',imageAlt:'Farleigh School education project by Darcy Construction',intro:'A verified repeat-client education relationship, delivered around school operations, holiday windows and the safety of staff and pupils.',snapshot:[{value:'Education',label:'Sector'},{value:'4 years',label:'Repeat client period'},{value:'Hybrid route',label:'Published delivery model'},{value:'Summer 2021',label:'Verified testimonial timing'} ],overview:'<p>The current Darcy website states that Farleigh School had been a repeat client of Darcy’s for the last four years.</p><p>Published work includes office fit-outs, a new reception area, new classrooms and corridors, dining room, medical centre, staff room, kitchen and external works.</p>',challenge:'<p>Farleigh’s projects needed to be delivered around a live school environment. The published Darcy copy states that many projects were undertaken during summer and holiday periods to ensure minimal disruption.</p><p>Darcy also had to consider live location, health and safety and the zoning of areas so staff and students were not disturbed or put at risk.</p>',approach:'<p>The published project page states that the Farleigh work used a hybrid of design and build and traditional delivery. Darcy managed some of the client’s consultants, utilised their services and coordinated with Darcy’s own design team.</p><p>This is strong evidence of the Darcy Standard in practice: collaboration, coordination and careful decision-making around the needs of the client environment.</p>',outcome:'<p>The verified testimonial describes a summer 2021 project converting an old sports building into three modern classrooms, an office for staff and circulation space for children.</p><p>The client states that Darcy worked within budgetary constraints, achieved excellent value for money in time for the autumn term and that the end result was much acclaimed by visitors, teachers and pupils.</p>',facts:[{label:'Project',value:'Farleigh School'},{label:'Client',value:'Farleigh School'},{label:'Sector',value:'Education'},{label:'Location',value:'To confirm with Darcy'},{label:'Scope',value:'Fit-outs, classrooms, reception, dining, medical, staff and external works'},{label:'Delivery route',value:'Hybrid design and build / traditional'},{label:'Verified timing',value:'Summer 2021 project completed in time for the autumn term'},{label:'Completion date',value:'To confirm with Darcy for full programme'} ],gallery:[{src:'https://darcyconstruction.co.uk/wp-content/uploads/2021/07/staff-room-4-2-scaled.jpg',alt:'Farleigh School completed education interior by Darcy Construction',caption:'Published Darcy project photography for Farleigh School.'} ],testimonial:{quote:'“After several previously successful projects we were delighted to work with Darcy Construction Limited again in the summer of 2021. They came up with imaginative ideas to convert an old sports building into three modern classrooms as well as an office for staff and circulation space for the children. Darcy readily accepted our budgetary constraints and worked with us to achieve excellent value for money in time for the autumn term. The end result is much acclaimed by visitors as well as the teachers and pupils that use them.”',name:'Farleigh School',context:'Education project testimonial'},related:[{title:'Sozo Ministries Conference Hall',story:'A place with purpose, protected through change.',image:'https://darcyconstruction.co.uk/wp-content/uploads/2021/07/community.jpg',href:'#case-study'},{title:'Canada Common',story:'A rural home shaped with patience and precision.',image:'https://darcyconstruction.co.uk/wp-content/uploads/2022/03/Capture.jpg',href:'#canada-common'},{title:'October Books',story:'A valued independent organisation given room for its next chapter.',image:'https://darcyconstruction.co.uk/wp-content/uploads/2022/02/NR174808-min-550x450@2x.jpg',href:'#work'} ],ctaTitle:'Planning work around a live school?',ctaBody:'Start with the operational reality. Darcy will help you shape a route that protects people, programme and confidence.'};return caseStudyTemplate(project);},insights() {const articles=[['Choosing the right construction partner','How do you know whether a contractor will listen, communicate clearly and stay accountable when the work becomes complex?'],['Construction Management explained','What does construction management actually mean, when is it useful and what responsibilities should a client expect to retain?'],['Planning a successful refurbishment','What should be understood before work begins on an existing building, especially when unknowns are likely to emerge?'],['Working safely in live school environments','How can schools plan building work around safeguarding, term dates, access, noise and the daily life of pupils and staff?'],['Budget certainty from pre-construction onwards','What creates a more reliable budget before construction starts, and how should risk, assumptions and decisions be communicated?'],['The value of early contractor involvement','When should a contractor join the conversation, and how can early buildability advice reduce later pressure?'],['How collaboration reduces project risk','Why do clients, consultants and contractors need a shared decision rhythm before small issues become expensive problems?'],['What to expect when you work with Darcy','What should the client experience feel like from the first conversation through planning, delivery, handover and aftercare?'] ];return `${hero('Insights','Practical thinking for clients who want to make confident construction decisions.','Guidance before selling')} <section class="section">${heading('Useful thinking','Answers worth sharing early.','Evergreen resources for clients making important decisions about planning, procurement, cost, delivery and trust.','insights-title')}<div class="insight-grid">${articles.map((a,i)=>`<article><span>Resource · ${String(i+1).padStart(2,'0')}</span><h3>${a[0]}</h3><p>${a[1]}</p><a href="#insights"aria-label="Read resource: ${a[0]}">Read the guide ${'→'}</a></article>`).join('')}</div></section> ${placeholder('Draft article bodies, authors, publication dates, SEO metadata and internal links require editorial production before launch.')} ${cta('Have a question before you have a project?')}`;},careers() {return `${hero('Join the team','Do work you can point to with pride, alongside people who care how it gets done.','Careers at Darcy')} ${editorialSplit({src:'https://darcyconstruction.co.uk/wp-content/uploads/2021/07/community-550x450x.jpg',alt:'A close team talking together',eyebrow:'Working at Darcy',title:'Serious about the work.<br>Human about everything else.',body:'<p>We are a close, experienced team where people are trusted to contribute, supported to grow and expected to care about clients, colleagues and craft.</p>',link:'#contact',label:'Introduce yourself'})} <section class="section">${heading('What matters here','Good people make good projects.','We value judgement, honesty, curiosity and the confidence to speak up early.','career-values')}${valueCards()}</section> ${placeholder('Confirm current vacancies, benefits, training commitments and application process before publication.')} ${cta('Think you would feel at home here?','Even when no role is advertised, we are always interested in meeting thoughtful construction people.','')}`;},contact() {return `${hero('Start a conversation','You do not need a finished brief. Tell us what you are considering and we will help you clarify the next step.','Contact Darcy')} <section class="section contact-grid"><div class="contact-details"><span class="eyebrow">Darcy Construction</span><h3>Romsey, Hampshire</h3><p><a href="tel:01794519545">01794 519545</a><br><a href="mailto:enquiries@darcyconstruction.co.uk">enquiries@darcyconstruction.co.uk</a></p><p>Unit 13 Westlink<br>Belbins Business Park<br>Cupernham Lane<br>Romsey, SO51 7JF</p><p>Monday–Friday<br>08:00–17:00</p></div><form id="contact-form" novalidate aria-describedby="contact-form-status"><div id="contact-form-status" class="form-status" role="status" aria-live="polite" aria-atomic="true"></div><label for="contact-name"><span>Name</span><input id="contact-name" name="name" autocomplete="name" required aria-describedby="contact-name-error"><span id="contact-name-error" class="field-error" role="alert"></span></label><label for="contact-email"><span>Email</span><input id="contact-email" name="email" type="email" autocomplete="email" required aria-describedby="contact-email-error"><span id="contact-email-error" class="field-error" role="alert"></span></label><label class="full" for="contact-project"><span>What are you considering?</span><select id="contact-project" name="enquiry"><option>A new project</option><option>Pre-construction advice</option><option>Working with Darcy</option><option>Something else</option></select></label><label class="full" for="contact-message"><span>Tell us a little more</span><textarea id="contact-message" name="message" aria-describedby="contact-message-error"></textarea><span id="contact-message-error" class="field-error" role="alert"></span></label><button class="button full" type="submit">Send enquiry <span aria-hidden="true">↗</span></button><p class="form-note full">We will respond using the contact details you provide.</p></form></section>`;} };window.DarcyPages =Object.freeze(Pages);})();